import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    result: list[str] = []

    if freq == "DAILY":
        return [
            (start_date + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    if freq == "WEEKLY":
        weekdays = sorted(wd_map[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(result) < count:
            monday = week0_monday + timedelta(days=w * k * 7)
            for wd in weekdays:
                d = monday + timedelta(days=wd)
                if d >= start_date:
                    result.append(d.isoformat())
                    if len(result) == count:
                        return result
            w += 1
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m_idx = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month0 = divmod(base_months + m_idx * k, 12)
                month = month0 + 1
                last_day = calendar.monthrange(year, month)[1]
                day = last_day if target_day == -1 else target_day
                if 1 <= day <= last_day:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_idx += 1
        else:
            n = int(parts[2])
            target_wd = wd_map[parts[3]]
            while len(result) < count:
                year, month0 = divmod(base_months + m_idx * k, 12)
                month = month0 + 1
                first_wd, last_day = calendar.monthrange(year, month)
                if n == -1:
                    last_wd = (first_wd + last_day - 1) % 7
                    day = last_day - (last_wd - target_wd) % 7
                else:
                    first_occ = 1 + (target_wd - first_wd) % 7
                    day = first_occ + (n - 1) * 7
                if 1 <= day <= last_day:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m_idx += 1
        return result

    if freq == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        y_idx = 0
        while len(result) < count:
            year = start_date.year + y_idx * k
            last_day = calendar.monthrange(year, month)[1]
            if day <= last_day:
                d = date(year, month, day)
                if d >= start_date:
                    result.append(d.isoformat())
            y_idx += 1
        return result

    raise ValueError(f"Unsupported rule: {rule}")
